"""Tests for fsutil.paths."""

import os
from pathlib import Path

import pytest

import fsutil


def _join(*parts: str) -> str:
    return os.path.join(*parts)


class TestJoinPath:
    def test_multiple_parts(self):
        assert fsutil.join_path("a", "b", "c") == _join("a", "b", "c")

    def test_absolute_first_part(self):
        assert fsutil.join_path("/tmp", "a", "b") == _join("/tmp", "a", "b")

    def test_accepts_pathlike(self):
        assert fsutil.join_path(Path("a"), Path("b")) == _join("a", "b")

    def test_returns_str(self):
        assert isinstance(fsutil.join_path(Path("a"), "b"), str)


class TestSplitPath:
    def test_relative_path(self):
        parts = fsutil.split_path(_join("a", "b", "c"))
        assert parts[-3:] == ["a", "b", "c"]

    def test_round_trip_relative(self):
        parts = fsutil.split_path(_join("a", "b", "c"))
        assert _join(*parts) == _join("a", "b", "c")

    def test_absolute_path_ends_with_parts(self):
        parts = fsutil.split_path(_join(os.sep, "a", "b", "c"))
        assert parts[-3:] == ["a", "b", "c"]


class TestSplitFilepath:
    def test_absolute(self):
        assert fsutil.split_filepath("/a/b/file.txt") == (_join("/a", "b"), "file.txt")

    def test_relative(self):
        assert fsutil.split_filepath(_join("a", "file.txt")) == ("a", "file.txt")


class TestSplitFilename:
    def test_pdf(self):
        assert fsutil.split_filename("document.pdf") == ("document", ".pdf")

    def test_no_extension(self):
        assert fsutil.split_filename("document") == ("document", "")


class TestGetFilename:
    def test_basic(self):
        assert fsutil.get_filename("/a/b/document.pdf") == "document.pdf"

    def test_pathlike(self):
        assert fsutil.get_filename(Path("a") / "document.pdf") == "document.pdf"


class TestGetFileBasename:
    def test_basic(self):
        assert fsutil.get_file_basename("/a/b/document.pdf") == "document"

    def test_no_extension(self):
        assert fsutil.get_file_basename("/a/b/document") == "document"


class TestGetFileExtension:
    def test_returns_dot_prefixed(self):
        assert fsutil.get_file_extension("document.pdf") == ".pdf"

    def test_full_path(self):
        assert fsutil.get_file_extension("/a/b/archive.tar.gz") == ".gz"

    def test_no_extension(self):
        assert fsutil.get_file_extension("document") == ""


class TestGetParentDir:
    def test_default_levels(self):
        assert fsutil.get_parent_dir(_join("/a", "b", "c")) == _join("/a", "b")

    def test_levels_1(self):
        assert fsutil.get_parent_dir(_join("/a", "b", "c"), levels=1) == _join("/a", "b")

    def test_levels_2(self):
        assert fsutil.get_parent_dir(_join("/a", "b", "c"), levels=2) == "/a"

    def test_levels_0_raises(self):
        with pytest.raises(ValueError):
            fsutil.get_parent_dir(_join("/a", "b"), levels=0)

    def test_negative_levels_raises(self):
        with pytest.raises(ValueError):
            fsutil.get_parent_dir(_join("/a", "b"), levels=-1)


class TestJoinFilename:
    def test_extension_with_dot(self):
        assert fsutil.join_filename("document", ".pdf") == "document.pdf"

    def test_extension_without_dot(self):
        assert fsutil.join_filename("document", "pdf") == "document.pdf"


class TestJoinFilepath:
    def test_basic(self):
        assert fsutil.join_filepath(_join("/a", "b"), "file.txt") == _join("/a", "b", "file.txt")

    def test_pathlike(self):
        assert fsutil.join_filepath(Path("a"), "file.txt") == _join("a", "file.txt")


class TestTransformFilepath:
    def test_upper_filename(self):
        result = fsutil.transform_filepath(_join("/a", "file.txt"), str.upper)
        assert result == _join("/a", "FILE.TXT")

    def test_custom_transform(self):
        result = fsutil.transform_filepath(
            _join("dir", "file.txt"), lambda name: "prefix_" + name
        )
        assert result == _join("dir", "prefix_file.txt")


class TestGetPath:
    def test_joins_subpaths(self):
        assert fsutil.get_path("/a", "b", "c") == _join("/a", "b", "c")

    def test_relative_returns_absolute(self):
        result = fsutil.get_path(_join("some", "relative", "path"))
        assert result == os.path.abspath(_join("some", "relative", "path"))

"""Tests for fsutil.checks."""

import pytest

import fsutil


@pytest.fixture
def existing_file(tmp_path):
    f = tmp_path / "file.txt"
    f.write_text("hello")
    return f


@pytest.fixture
def existing_dir(tmp_path):
    d = tmp_path / "subdir"
    d.mkdir()
    return d


@pytest.fixture
def missing_path(tmp_path):
    return tmp_path / "does_not_exist"


class TestExists:
    def test_existing_file(self, existing_file):
        assert fsutil.exists(existing_file) is True

    def test_existing_dir(self, existing_dir):
        assert fsutil.exists(existing_dir) is True

    def test_missing(self, missing_path):
        assert fsutil.exists(missing_path) is False


class TestAssertExists:
    def test_existing_ok(self, existing_file):
        fsutil.assert_exists(existing_file)

    def test_missing_raises(self, missing_path):
        with pytest.raises(fsutil.FSUtilError):
            fsutil.assert_exists(missing_path)


class TestAssertNotExists:
    def test_missing_ok(self, missing_path):
        fsutil.assert_not_exists(missing_path)

    def test_existing_raises(self, existing_file):
        with pytest.raises(fsutil.FSUtilError):
            fsutil.assert_not_exists(existing_file)


class TestIsFileIsDir:
    def test_file(self, existing_file):
        assert fsutil.is_file(existing_file) is True
        assert fsutil.is_dir(existing_file) is False

    def test_dir(self, existing_dir):
        assert fsutil.is_dir(existing_dir) is True
        assert fsutil.is_file(existing_dir) is False

    def test_missing(self, missing_path):
        assert fsutil.is_file(missing_path) is False
        assert fsutil.is_dir(missing_path) is False


class TestAssertFile:
    def test_file_ok(self, existing_file):
        fsutil.assert_file(existing_file)

    def test_dir_raises(self, existing_dir):
        with pytest.raises(fsutil.FSUtilError):
            fsutil.assert_file(existing_dir)

    def test_missing_raises(self, missing_path):
        with pytest.raises(fsutil.FSUtilError):
            fsutil.assert_file(missing_path)


class TestAssertDir:
    def test_dir_ok(self, existing_dir):
        fsutil.assert_dir(existing_dir)

    def test_file_raises(self, existing_file):
        with pytest.raises(fsutil.FSUtilError):
            fsutil.assert_dir(existing_file)

    def test_missing_raises(self, missing_path):
        with pytest.raises(fsutil.FSUtilError):
            fsutil.assert_dir(missing_path)


class TestAssertNotFile:
    def test_dir_ok(self, existing_dir):
        fsutil.assert_not_file(existing_dir)

    def test_file_raises(self, existing_file):
        with pytest.raises(fsutil.FSUtilError):
            fsutil.assert_not_file(existing_file)


class TestAssertNotDir:
    def test_file_ok(self, existing_file):
        fsutil.assert_not_dir(existing_file)

    def test_dir_raises(self, existing_dir):
        with pytest.raises(fsutil.FSUtilError):
            fsutil.assert_not_dir(existing_dir)


class TestIsEmpty:
    def test_empty_file(self, tmp_path):
        f = tmp_path / "empty.txt"
        f.touch()
        assert fsutil.is_empty(f) is True

    def test_non_empty_file(self, existing_file):
        assert fsutil.is_empty(existing_file) is False

    def test_empty_dir(self, existing_dir):
        assert fsutil.is_empty(existing_dir) is True

    def test_non_empty_dir(self, existing_dir, tmp_path):
        (existing_dir / "child.txt").write_text("x")
        assert fsutil.is_empty(existing_dir) is False


class TestIsEmptyFile:
    def test_empty_file(self, tmp_path):
        f = tmp_path / "empty.txt"
        f.touch()
        assert fsutil.is_empty_file(f) is True

    def test_non_empty_file(self, existing_file):
        assert fsutil.is_empty_file(existing_file) is False


class TestIsEmptyDir:
    def test_empty_dir(self, existing_dir):
        assert fsutil.is_empty_dir(existing_dir) is True

    def test_non_empty_dir(self, existing_dir):
        (existing_dir / "child.txt").write_text("x")
        assert fsutil.is_empty_dir(existing_dir) is False

"""Tests for fsutil.converters."""

import pytest

import fsutil


class TestConvertSizeBytesToString:
    def test_zero(self):
        assert fsutil.convert_size_bytes_to_string(0) == "0B"

    def test_kilobytes(self):
        assert fsutil.convert_size_bytes_to_string(1536) == "1.5 KB"

    def test_megabytes(self):
        assert fsutil.convert_size_bytes_to_string(1048576) == "1.0 MB"

    def test_gigabytes(self):
        assert fsutil.convert_size_bytes_to_string(2 * 1024**3) == "2.0 GB"


class TestConvertSizeStringToBytes:
    def test_megabytes(self):
        assert fsutil.convert_size_string_to_bytes("2.5 MB") == 2621440

    def test_bytes(self):
        assert fsutil.convert_size_string_to_bytes("512 B") == 512

    def test_kilobytes(self):
        assert fsutil.convert_size_string_to_bytes("1.5 KB") == 1536

    def test_invalid_raises(self):
        with pytest.raises(ValueError):
            fsutil.convert_size_string_to_bytes("not a size")

    def test_invalid_unit_raises(self):
        with pytest.raises(ValueError):
            fsutil.convert_size_string_to_bytes("10 XB")


class TestRoundTrip:
    @pytest.mark.parametrize(
        "size",
        [512, 1024, 1536, 1048576, 3 * 1024**2, 5 * 1024**3],
    )
    def test_round_trip(self, size):
        s = fsutil.convert_size_bytes_to_string(size)
        assert fsutil.convert_size_string_to_bytes(s) == size
